// Golden outputs generated from the original TypeScript composer builder and serializer.
// Inputs are literals from its existing rich-text, block, inline-text, and mention test suites.
use serde_json::{Value, json};
use t3_client::thread_views::composer::editor::{BuildOptions, build_document, serialize_document};
fn canonical(value: &mut Value) {
    match value {
        Value::Array(values) => {
            for value in values {
                canonical(value);
            }
        }
        Value::Object(values) => {
            values.retain(|key, value| {
                key != "citeKey"
                    && !(matches!(key.as_str(), "content" | "marks")
                        && value.as_array().is_some_and(Vec::is_empty))
                    && !(key == "attrs" && value.as_object().is_some_and(serde_json::Map::is_empty))
            });
            for value in values.values_mut() {
                canonical(value);
            }
        }
        _ => {}
    }
}
fn first_difference(expected: &Value, actual: Value) -> Option<usize> {
    let expected = expected.as_array().expect("golden array");
    let actual = actual.as_array().expect("actual array");
    (0..expected.len().max(actual.len())).find(|index| expected.get(*index) != actual.get(*index))
}
#[test]
fn typescript_builder_serializer_and_every_position_map_offset_match() {
    let cases: Vec<Value> = serde_json::from_str(GOLDENS).expect("goldens");
    let mut failures = vec![];
    for case in cases {
        let source = case["text"].as_str().expect("source");
        let mut document = build_document(
            source,
            BuildOptions::default(),
            |name| Some((name.into(), None)),
            |_, _| false,
        );
        canonical(&mut document);
        let map = serialize_document(&document);
        let mut mismatch = vec![];
        if document != case["tree"] {
            mismatch.push("tree".to_owned());
        }
        if json!(map.value) != case["value"] {
            mismatch.push(format!("value {:?} != {:?}", map.value, case["value"]));
        }
        if json!(map.doc_length) != case["docLength"] {
            mismatch.push("docLength".into());
        }
        if json!(map.context_ids) != case["contextIds"] {
            mismatch.push("contextIds".into());
        }
        for (name, actual) in [
            (
                "flatMd",
                json!(
                    (0..case["flatMd"].as_array().expect("array").len())
                        .map(|offset| map.flat_to_markdown(offset))
                        .collect::<Vec<_>>()
                ),
            ),
            (
                "flatPm",
                json!(
                    (0..case["flatPm"].as_array().expect("array").len())
                        .map(|offset| map.flat_to_pm(offset))
                        .collect::<Vec<_>>()
                ),
            ),
            (
                "mdFlat",
                json!(
                    (0..case["mdFlat"].as_array().expect("array").len())
                        .map(|offset| map.markdown_to_flat(offset))
                        .collect::<Vec<_>>()
                ),
            ),
            (
                "pmFlat",
                json!(
                    (0..case["pmFlat"].as_array().expect("array").len())
                        .map(|offset| map.pm_to_flat(offset))
                        .collect::<Vec<_>>()
                ),
            ),
        ] {
            if let Some(offset) = first_difference(&case[name], actual) {
                mismatch.push(format!("{name}@{offset}"));
            }
        }
        if !mismatch.is_empty() {
            failures.push(format!(
                "{:?}: {}",
                source.chars().take(180).collect::<String>(),
                mismatch.join(", ")
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches; first 40:\n{}",
        failures.len(),
        failures
            .iter()
            .take(40)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
